'use strict';
/* COLLISION AUDIT — is 251,505 twice a coincidence?
 *
 * This repository measured the same six-digit number twice, from constructions
 * that share nothing:
 *
 *   R3/U2  the monoid generated by positionwise operations plus one translation,
 *          acting on a width-2 arena, has exactly 251,505 elements;
 *   E4/F3  the decoded six-trit adder settles in exactly thirteen passes on
 *          exactly 251,505 of its 531,441 operand pairs.
 *
 * And the larger number collides too: the arbitrary-carry monoid closes at
 * 531,441, which is also the number of operand pairs. So BOTH terms of a ratio
 * match, and the ratio is 115/243 on both sides. F-251505-AGAIN recorded this and
 * declined to chase it. This chases it.
 *
 * The pairing that produces the collision is monoid width w against an adder of
 * 3w trits: w = 2 gives both 531,441 and 251,505 on both sides. So the question
 * is whether that pairing is a law or an accident, and the way to find out is to
 * evaluate it somewhere else — which means w = 1 against a three-trit adder,
 * since w = 3 is a monoid on 27 points with a function space of 27^27.
 *
 * ------------------------------------------------------------------------------
 * NOT REGISTERED. Established while setting this up, because a coincidence
 * between two numbers is not worth a minute of anyone's time until both numbers
 * are known to be real:
 *
 *   - 251,505 is a CLOSED monoid, saturated at depth, nowhere near its cap;
 *   - 531,441 is likewise closed and saturated, at a cap of 1,200,000, and is
 *     not the cap. It is a lower bound on the arbitrary-carry reach because its
 *     generators are sampled, but the monoid those generators close on is
 *     exactly that size;
 *   - 251,505 = 3^7 x 115, and 531,441 = 3^12, and 251505/531441 = 115/243.
 *
 * PREDICTED OUTCOMES — registered BEFORE the run, in their own commit.
 *
 *   G1  THE CORRESPONDENCE DIES AT THE FIRST OTHER PARAMETER, and not narrowly.
 *       At width 1 the monoid acts on three points, so its entire universe is
 *       3^3 = 27 functions — every monoid at that width, whatever its vocabulary,
 *       is at most 27. The three-trit adder has 729 operand pairs of which 621
 *       settle late. Both adder numbers are larger than the whole space the
 *       monoid side lives in.
 *
 *       Predicted: the width-1 reach is 27 for the arbitrary-carry vocabulary AND
 *       27 for the one-translation vocabulary — at a single position the
 *       positionwise maps already give every unary function, and a translation
 *       cannot add to a set that is already everything. Against 729 and 621. No
 *       correspondence survives, and it is not close.
 *
 *   G2  AND THE TWO FAMILIES GROW AT INCOMPATIBLE RATES, so they were never the
 *       same sequence sampled at different points. The adder counts obey a linear
 *       recurrence, derived by hand from the transfer matrix's characteristic
 *       polynomial:
 *
 *           s(k+1) = 9 s(k) - 12 s(k-1),   roots (9 +/- sqrt 33) / 2
 *
 *       so successive counts multiply by about 7.37 and the growth rate is
 *       irrational. The monoid reaches go 27 at width 1 to 251,505 at width 2 — a
 *       factor of about 9,315.
 *
 *       Predicted: the recurrence reproduces every measured adder count and
 *       extends to widths 7 through 12; the monoid growth factor exceeds the
 *       adder's by more than 1,000x; and no adder count anywhere in the sequence
 *       equals a monoid reach other than at the one point already known.
 *
 *   G3  THE 531,441 COLLISION HAS AN ARITHMETIC EXPLANATION AND THE 251,505 ONE
 *       DOES NOT. The two denominators are 3^3 and 3^12 on the monoid side at
 *       widths 1 and 2, and 3^6 and 3^12 on the adder side at 3 and 6 trits.
 *       They differ at the first and agree at the second: one crossing, not a
 *       pattern. Predicted exactly that — 27 against 729, then 531,441 against
 *       531,441.
 *
 *       NOT claimed: any formula for how the monoid ceiling grows with width. Two
 *       data points do not determine one, and nothing here needs it.
 *
 *   G4  AND COLLISIONS OF THIS SIZE ARE RARE HERE, WHICH IS WHY IT LOOKED LIKE
 *       SOMETHING. Sweeping every measured integer in FINDINGS.json, exactly two
 *       distinct values of 1,000 or more appear in two or more prediction sets
 *       that measure different things: 531,441 and 251,505. Predicted: exactly
 *       two, and those two.
 *
 *       If the count comes back higher, the right conclusion is the opposite of
 *       the one this tool was built to test — that six-digit collisions are
 *       common in a repository that counts everything in powers of three, and
 *       noticing one says more about the noticer than the numbers.
 * ------------------------------------------------------------------------------
 */

const path = require('path');
const fs = require('fs');
const L = require('../tools/monoid-lib.js');
const T = require('../src/ternary.js');

const line = '='.repeat(78);
console.log('COLLISION AUDIT — 251,505 turned up twice. Is that anything?\n');

/* --- the adder side: pure arithmetic, no circuit needed --------------------- */
const carry = x => T.shiftRight(x, 1);
const STATES = [-1, 0, 1];
const MATRIX = STATES.map(c => {
  const row = { '-1': 0, 0: 0, 1: 0 };
  for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) {
    const s = a + b;
    if (c !== 0 && carry(s + c) === carry(s)) continue;
    row[carry(s + c)] += 1;
  }
  return STATES.map(x => row[x]);
});
const V0 = STATES.map(target => {
  let k = 0;
  for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) if (carry(a + b) === target) k++;
  return k;
});
const stepV = v => STATES.map((_, j) => v.reduce((acc, x, i) => acc + x * MATRIX[i][j], 0));
const sumV = v => v.reduce((x, y) => x + y, 0);

/** Adder counts: how many operand pairs settle in the full (2n+1) passes. */
function adderLateCount(n) {
  let v = V0;
  for (let k = 0; k < n - 2; k++) v = stepV(v);
  return 9 * sumV(v);
}
const adderPairs = n => Math.pow(9, n);

console.log('--- G1  evaluate the pairing somewhere other than where it was noticed ---');
{
  console.log('      pairing: monoid width w  <->  adder of 3w trits\n');
  console.log('      w   monoid universe   monoid: any carry   one translation'
    + '   | adder pairs   settle late');
  for (const w of [1, 2]) {
    const A = L.arena(w);
    const universe = `${A.N}^${A.N}`;
    const anyCarry = L.audit(L.topSinglePos(A).concat(L.topcSample(A, 40)), A.N, 100, 1200000);
    const oneTrans = L.audit(L.topSinglePos(A).concat([L.addTable(A, 1)]), A.N, 100, 1200000);
    const n = 3 * w;
    console.log(`      ${w}   ${universe.padEnd(15)}   ${String(anyCarry.total).padStart(17)}`
      + `   ${String(oneTrans.total).padStart(15)}`
      + `   | ${String(adderPairs(n)).padStart(11)}   ${String(adderLateCount(n)).padStart(11)}`);
    if (w === 1) {
      const cap = Math.pow(A.N, A.N);
      console.log(`          at width 1 EVERY monoid is at most ${cap}, and the adder`
        + ` numbers are ${adderPairs(3)} and ${adderLateCount(3)}.`);
      console.log(`          ${cap < adderLateCount(3)
        ? 'The monoid universe is smaller than the adder number it would have to match.'
        : 'The universe is large enough that the comparison is not vacuous.'}`);
    }
  }
}

console.log('\n--- G2  do the two families even grow alike? ---');
{
  let ok = true;
  const counts = [];
  for (let n = 2; n <= 12; n++) counts.push(adderLateCount(n));
  for (let i = 2; i < counts.length; i++) {
    if (counts[i] !== 9 * counts[i - 1] - 12 * counts[i - 2]) ok = false;
  }
  console.log(`      adder counts, widths 2..12:`);
  console.log('        ' + counts.map(c => c.toLocaleString()).join(', '));
  console.log(`      s(k+1) = 9 s(k) - 12 s(k-1) holds at every step: ${ok}`);
  const root = (9 + Math.sqrt(33)) / 2;
  console.log(`      dominant root (9 + sqrt 33)/2 = ${root.toFixed(6)}`
    + `   last measured ratio ${(counts[counts.length - 1] / counts[counts.length - 2]).toFixed(6)}`);

  const A1 = L.arena(1), A2 = L.arena(2);
  const m1 = L.audit(L.topSinglePos(A1).concat([L.addTable(A1, 1)]), A1.N, 100, 1200000).total;
  const m2 = L.audit(L.topSinglePos(A2).concat([L.addTable(A2, 1)]), A2.N, 100, 1200000).total;
  console.log(`      monoid one-translation: width 1 = ${m1}, width 2 = ${m2.toLocaleString()}`
    + `   factor ${(m2 / m1).toFixed(0)}`);
  console.log(`      adder growth factor ${root.toFixed(2)} against monoid ${(m2 / m1).toFixed(0)}`
    + `   — ${(m2 / m1 / root).toFixed(0)}x apart`);

  // Does any adder count in a generous range equal a monoid reach we have?
  const monoidReaches = new Set([3, 7, 9, 11, 27, 29, 47, 307, 729, 801, 19683, 251505, 531441,
    387420489, m1, m2]);
  const hits = counts.filter(c => monoidReaches.has(c));
  console.log(`      adder counts that equal any recorded monoid reach: `
    + `${hits.length ? hits.map(h => h.toLocaleString()).join(', ') : 'none'}`);
}

console.log('\n--- G3  the denominators: one crossing, or a pattern? ---');
{
  console.log('      w   monoid universe of reachable size   adder operand pairs (3w trits)');
  for (const w of [1, 2]) {
    const A = L.arena(w);
    const anyCarry = L.audit(L.topSinglePos(A).concat(L.topcSample(A, 40)), A.N, 100, 1200000).total;
    const pairs = adderPairs(3 * w);
    const p3 = x => { let e = 0, y = x; while (y % 3 === 0) { y /= 3; e++; } return y === 1 ? `3^${e}` : String(x); };
    console.log(`      ${w}   ${String(anyCarry).padStart(10)} = ${p3(anyCarry).padEnd(6)}`
      + `                ${String(pairs).padStart(10)} = ${p3(pairs).padEnd(6)}`
      + `   ${anyCarry === pairs ? '<- COLLIDE' : 'differ'}`);
  }
  console.log('      No formula is claimed for how the monoid ceiling grows. Two points do not');
  console.log('      fix one, and the question here does not need it.');
}

console.log('\n--- G4  how rare is a collision of this size in this repository? ---');
{
  const M = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'FINDINGS.json'), 'utf8'));

  /* "Prediction sets that measure DIFFERENT THINGS" was in the registration, and
   * the first version of this loop dropped the clause -- counting a quantity
   * restated in a second set as a collision with itself. Which half of the
   * project a set belongs to is DERIVED from what its tool imports rather than
   * hardcoded: the vocabulary work is built on monoid-lib, the circuit work on
   * device.js. A collision worth the name crosses that line. */
  const half = st => {
    const src = fs.readFileSync(path.join(__dirname, '..', st.tool), 'utf8');
    if (/require\([^)]*monoid-lib/.test(src)) return 'vocabulary';
    if (/require\([^)]*device\.js/.test(src)) return 'circuit';
    return 'other';
  };
  const sides = new Map(M.prediction_sets.map(st => [st.id, half(st)]));
  console.log('      halves, derived from what each tool imports:');
  for (const side of ['vocabulary', 'circuit', 'other']) {
    const ids = [...sides].filter(([, v]) => v === side).map(([k]) => k);
    if (ids.length) console.log(`        ${side.padEnd(11)} ${ids.sort().join(', ')}`);
  }

  const where = new Map();
  for (const st of M.prediction_sets) {
    for (const p of st.predictions) {
      const ints = [...JSON.stringify(p.measured || {}).matchAll(/(\d{4,})/g)].map(x => Number(x[1]));
      for (const v of new Set(ints)) {
        if (!where.has(v)) where.set(v, new Set());
        where.get(v).add(st.id);
      }
    }
  }
  const repeated = [...where.entries()].filter(([v, ids]) => v >= 1000 && ids.size >= 2);
  const crossing = repeated.filter(([, ids]) => new Set([...ids].map(id => sides.get(id))).size >= 2);

  console.log(`\n      integers >= 1000 in two or more sets, ANY sets: ${repeated.length}`);
  for (const [v, ids] of repeated.sort((x, y) => y[0] - x[0])) {
    const halves = [...new Set([...ids].map(id => sides.get(id)))].sort();
    console.log(`        ${String(v).padStart(10)}  sets ${[...ids].sort().join(', ').padEnd(18)}`
      + `  ${halves.length >= 2 ? 'CROSSES the halves' : halves[0] + ' only - a restatement, not a collision'}`);
  }
  console.log(`\n      crossing both halves, which is what was registered: ${crossing.length}`
    + `   (predicted 2)`);
  console.log(`        ${crossing.map(([v]) => v.toLocaleString()).sort().join(', ')}`);
}

console.log('\n' + line);
